<?php require 'config.php'; $u=require_login(); $type=($_GET['type']??'youtuber')==='beta'?'beta':'youtuber';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$age=(int)($_POST['age']??0);$months=(int)($_POST['months']??0);$sub=(int)($_POST['subscribers']??0);if($type==='beta'&&($age<17||$months<1))$err='Для Beta Tester нужен возраст от 17 лет и минимум 1 месяц опыта.';elseif($type==='youtuber'&&($sub<500))$err='Для Creator минимально 500 подписчиков.';else{$s=db()->prepare('INSERT INTO applications(user_id,type,name,age,youtube,tiktok,views,subscribers,experience,months,discord,vk,reason,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$u['id'],$type,$_POST['name']??$u['username'],$age,$_POST['youtube']??'',$_POST['tiktok']??'',$_POST['views']??'', $sub,$_POST['experience']??'', $months,$_POST['discord']??'',$_POST['vk']??'',$_POST['reason']??'',time()]);flash('Заявка отправлена на рассмотрение.');header('Location: dashboard.php');exit;}}?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Заявка — Fly Client</title><link rel="stylesheet" href="assets/style.css"></head><body><?php require 'header.php'; ?><div class="wrap"><form class="form card" method="post"><h1><?=$type==='beta'?'Beta Tester':'Creator'?></h1><?php if($err):?><div class="notice danger"><?=e($err)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="label">Имя / ник</label><input class="input" name="name" value="<?=e($u['username'])?>"><label class="label">Возраст</label><input class="input" type="number" name="age" min="1"><?php if($type==='youtuber'):?><label class="label">YouTube</label><input class="input" name="youtube"><label class="label">TikTok</label><input class="input" name="tiktok"><label class="label">Подписчики</label><input class="input" type="number" name="subscribers"><label class="label">Просмотры на видео</label><input class="input" name="views"><p class="muted">Минимум: 500 подписчиков и 1500 просмотров на каждом видео.</p><?php else:?><label class="label">Стаж создания клиентов (месяцев)</label><input class="input" type="number" name="months" min="0"><label class="label">Опыт создания клиентов</label><textarea class="input" name="experience" rows="4"></textarea><?php endif;?><label class="label">Discord</label><input class="input" name="discord"><label class="label">VK</label><input class="input" name="vk"><label class="label">Почему хотите получить доступ?</label><textarea class="input" name="reason" rows="5"></textarea><button class="btn primary" style="width:100%">Отправить заявку</button></form></div></body></html>
